    // S2135. The call of a lambda is the right side of a coalescing operator whose left side has a value.
    public static Cell<int> PlainThroughALambdaAfterACoalescingOperator() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<SettableSlot, int> plain = given => { given.Share = Plain; return 0; }; SettableSlot x = new() { Share = l.Map(v => v) }; int? known = Kept.Count >= 0 ? 1 : null; int n = known ?? plain(x); Kept.Add(n); return S.Hold(x.Share!.Sample()); });

    // S2136. A local is one of an object of the store and an object with no state that the walk did not see made. A pending cell goes through the local, and a plain cell then goes through the name of the object of the store.
    public static Cell<int> LocalThatIsOneOfAnObjectOfTheStoreAndAnObjectWithNoState() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new(); SettableSlot c = Never ? x : SlotsOfNoObject[0]; c.Share = l.Map(v => v); x.Share = Plain; return S.Hold(c.Share!.Sample()); });

    // S2137. The same, where an assignment in a branch gives the local the second object.
    public static Cell<int> LocalThatABranchGivesAnObjectWithNoState() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new(); SettableSlot c = x; if (!Never) { c = SlotsOfNoObject[1]; } c.Share = l.Map(v => v); x.Share = Plain; return S.Hold(c.Share!.Sample()); });

    // S2138. The same, where a coalescing operator gives the object with no state.
    public static Cell<int> LocalFromACoalescingOperatorWithAnObjectWithNoState() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new(); SettableSlot? first = Never ? null : SlotsOfNoObject[2]; SettableSlot c = first ?? x; c.Share = l.Map(v => v); x.Share = Plain; return S.Hold(c.Share!.Sample()); });

    // S2139. A local is one of an object of the store and a null literal. A plain cell through the local replaces the pending cell of the object.
    public static Cell<int> LocalThatIsOneOfAnObjectOfTheStoreAndNull() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; SettableSlot? c = Kept.Count >= 0 ? x : null; c!.Share = Plain; return S.Hold(x.Share!.Sample()); });

    // S2140. The same, where the second value is a local that only has a null literal.
    public static Cell<int> LocalThatIsOneOfAnObjectOfTheStoreAndALocalWithNull() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; SettableSlot? none = null; SettableSlot c = none ?? x; c.Share = Plain; return S.Hold(x.Share!.Sample()); });

    // S2141. A method with no body to read keeps an object with a pending cell, and the indexer of its owner gives the object back.
    public static Cell<int> ElementOfAnObjectThatKeepsThroughAnInterface() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; ISlotBag bag = NewSlotBag(); bag.Put(x); bag[1] = new SettableSlot { Share = Plain }; return S.Hold(bag[0].Share!.Sample()); });

    // S2142. The same, where the object gets a plain cell after the call.
    public static Cell<int> ElementOfAnObjectThatKeepsThroughAnInterfaceAndGetsAPlainCell() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; ISlotBag bag = NewSlotBag(); bag.Put(x); x.Share = Plain; return S.Hold(bag[0].Share!.Sample()); });

    // S2143. The same, where the object gets its pending cell after the call.
    public static Cell<int> ElementOfAnObjectThatKeepsThroughAnInterfaceAndGetsAPendingCell() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = Plain }; ISlotBag bag = NewSlotBag(); bag.Put(x); x.Share = l.Map(v => v); return S.Hold(bag[0].Share!.Sample()); });

    // S2144. The second turn calls the lambda of the first turn, which samples a cell of a local of its own turn.
    public static Cell<int> LambdaOfTheTurnBeforeReadsALocalOfItsTurn() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<int>? read = null; for (int i = 0; i < 2; i++) { if (read != null) { Kept.Add(read()); } SettableSlot x = new() { Share = l.Map(v => v) }; read = () => x.Share!.Sample(); } return S.Hold(0); });

    // S2145. The same, where the local of the turn has a plain cell.
    public static Cell<int> LambdaOfTheTurnBeforeReadsAPlainLocalOfItsTurn() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<int>? read = null; for (int i = 0; i < 2; i++) { if (read != null) { Kept.Add(read()); } SettableSlot x = new() { Share = Plain }; read = () => x.Share!.Sample(); } return S.Hold(0); });

    // S2146. The same for a local function of the body that a local of the block keeps.
    public static Cell<int> LocalFunctionOfTheTurnBeforeReadsALocalOfItsTurn() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<int>? read = null; for (int i = 0; i < 2; i++) { if (read != null) { Kept.Add(read()); } SettableSlot x = new() { Share = l.Map(v => v) }; int Read() => x.Share!.Sample(); read = Read; } return S.Hold(0); });

    // S2147. First of a list that only a collection expression filled reads the state that its object has now.
    public static Cell<int> FirstOfALiteralReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> one = [x]; x.Share = Plain; return S.Hold(one.First().Share!.Sample()); });

    // S2148. First of a list reads the state that its object has now.
    public static Cell<int> FirstOfAListReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> list = []; list.Add(x); x.Share = Plain; return S.Hold(list.First().Share!.Sample()); });

    // S2149. The same for Last.
    public static Cell<int> LastOfAListReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> list = []; list.Add(x); x.Share = Plain; return S.Hold(list.Last().Share!.Sample()); });

    // S2150. The same for Single.
    public static Cell<int> SingleOfAListReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> list = []; list.Add(x); x.Share = Plain; return S.Hold(list.Single().Share!.Sample()); });

    // S2151. The same for ElementAt.
    public static Cell<int> ElementAtOfAListReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> list = []; list.Add(x); x.Share = Plain; return S.Hold(list.ElementAt(0).Share!.Sample()); });

    // S2152. The same for Find of a list.
    public static Cell<int> FindOfAListReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> list = []; list.Add(x); x.Share = Plain; return S.Hold(list.Find(s => s != null)!.Share!.Sample()); });

    // S2153. The same for First of the values of a dictionary.
    public static Cell<int> FirstOfTheValuesOfADictionaryReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; Dictionary<string, SettableSlot> map = new() { ["a"] = x }; x.Share = Plain; return S.Hold(map.Values.First().Share!.Sample()); });

    // S2154. First of a list gives an object that got its pending cell after the list got the object.
    public static Cell<int> FirstOfAListReadsAPendingCell() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = Plain }; List<SettableSlot> list = []; list.Add(x); x.Share = l.Map(v => v); return S.Hold(list.First().Share!.Sample()); });

    // S2155. First of a list gives an object that the walk did not see made, which has a pending cell. The list got an object of the store after it.
    public static Cell<int> FirstOfAListWithAnObjectThatTheWalkDidNotSeeMade() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot old = SlotsOfNoObject[0]; old.Share = l.Map(v => v); List<SettableSlot> list = []; list.Add(old); list.Add(new SettableSlot { Share = Plain }); return S.Hold(list.First().Share!.Sample()); });

    // S2156. Last of a list gives an object that the walk did not see made, which got a pending cell through its index.
    public static Cell<int> LastOfAListAfterAChangeThroughAnElement() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = Plain }; List<SettableSlot> list = []; list.Add(x); list.Add(SlotsOfNoObject[1]); list[1].Share = l.Map(v => v); x.Share = Plain; return S.Hold(list.Last().Share!.Sample()); });

    // S2157. A list gets its elements from a query over a second list. An element reads the state that its object has now.
    public static Cell<int> ElementsOfAQueryGoIn() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> first = [x]; List<SettableSlot> list = []; list.AddRange(first.Where(s => s != null)); x.Share = Plain; return S.Hold(list[0].Share!.Sample()); });

    // S2158. The same for a copy of the second list as an array.
    public static Cell<int> ElementsOfACopyGoIn() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> first = [x]; List<SettableSlot> list = []; list.AddRange(first.ToArray()); x.Share = Plain; return S.Hold(list[0].Share!.Sample()); });

    // S2159. A copy of a list from ToList has the same objects, and an element reads the state that its object has now.
    public static Cell<int> ElementOfAToListReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> first = [x]; List<SettableSlot> copy = first.ToList(); x.Share = Plain; return S.Hold(copy[0].Share!.Sample()); });

    // S2160. The same for a copy from the constructor of a list.
    public static Cell<int> ElementOfAListFromAListReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> first = [x]; List<SettableSlot> copy = new(first); x.Share = Plain; return S.Hold(copy[0].Share!.Sample()); });

    // S2161. The same for a copy from a spread.
    public static Cell<int> ElementOfASpreadReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> first = [x]; SettableSlot[] copy = [.. first]; x.Share = Plain; int i = Kept.Count >= 0 ? 0 : 1; return S.Hold(copy[i].Share!.Sample()); });

    // S2162. The same for the first element of a query.
    public static Cell<int> FirstOfAQueryReadsTheStateOfItsObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot> first = [x]; x.Share = Plain; return S.Hold(first.Where(s => s != null).First().Share!.Sample()); });

    // S2163. A copy of a list has an object that gets its pending cell after the copy.
    public static Cell<int> ElementOfAToListThatGetsAPendingCell() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = Plain }; List<SettableSlot> first = [x]; List<SettableSlot> copy = first.ToList(); x.Share = l.Map(v => v); return S.Hold(copy[0].Share!.Sample()); });

    // S2164. A second list has an object that the walk did not see made, which has a pending cell. A list gets its elements from a query over the second list.
    public static Cell<int> ElementsOfAQueryOverAnObjectThatTheWalkDidNotSeeMade() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot old = SlotsOfNoObject[2]; old.Share = l.Map(v => v); List<SettableSlot> first = []; first.Add(old); List<SettableSlot> list = []; list.AddRange(first.Where(s => s != null)); list.Add(new SettableSlot { Share = Plain }); return S.Hold(list[0].Share!.Sample()); });

    // S2165. A key of a dictionary is not one of the values that the dictionary holds. First of a copy of the keys gives the key with the pending cell.
    public static Cell<int> KeyThroughACopyOfKeys() =>
        Cell.Loop<int>().WithoutCaptures(l => { Dictionary<Titled, Titled> d = new(); d[new Titled(l.Map(v => v))] = new Titled(Plain); Kept.Add(d.Keys.ToList().First().ToString()); return S.Hold(0); });

    // S2166. The same for the first key of a loop over the keys.
    public static Cell<int> KeyThroughALoopOverKeys() =>
        Cell.Loop<int>().WithoutCaptures(l => { Dictionary<Titled, Titled> d = new(); d[new Titled(l.Map(v => v))] = new Titled(Plain); foreach (Titled key in d.Keys) { Kept.Add(key.ToString()); } return S.Hold(0); });

    // S2167. First of the values of the same dictionary gives the value, which has a plain cell.
    public static Cell<int> ValueThroughValuesBesideAKeyWithAPendingCell() =>
        Cell.Loop<int>().WithoutCaptures(l => { Dictionary<Titled, Titled> d = new(); d[new Titled(l.Map(v => v))] = new Titled(Plain); Kept.Add(d.Values.First().ToString()); return S.Hold(0); });

    // S2168. FirstOrDefault of an empty list gives its argument, which has a pending cell.
    public static Cell<int> FirstOrDefaultGivesItsArgument() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot fallback = new() { Share = l.Map(v => v) }; List<SettableSlot> list = []; return S.Hold(list.FirstOrDefault(fallback).Share!.Sample()); });

    // S2169. The same, where the list has an object with a plain cell and a query gives no element.
    public static Cell<int> FirstOrDefaultOfAQueryGivesItsArgument() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot fallback = new() { Share = l.Map(v => v) }; List<SettableSlot> list = [new SettableSlot { Share = Plain }]; return S.Hold(list.Where(s => s == null).FirstOrDefault(fallback).Share!.Sample()); });

    // S2170. The first Add to an empty builder of an ImmutableHashSet compares nothing.
    public static Cell<int> FirstAddToAnEmptyBuilderOfAnImmutableHashSet() =>
        Cell.Loop<int>().WithoutCaptures(l => { ImmutableHashSet<SameOwn>.Builder made = ImmutableHashSet.CreateBuilder<SameOwn>(); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2171. The same for an empty HashSet.
    public static Cell<int> FirstAddToAnEmptyHashSet() =>
        Cell.Loop<int>().WithoutCaptures(l => { HashSet<SameOwn> made = new(); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2172. The same for an empty SortedSet.
    public static Cell<int> FirstAddToAnEmptySortedSet() =>
        Cell.Loop<int>().WithoutCaptures(l => { SortedSet<RankedOwn> made = new(); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2173. The same for the Empty of an ImmutableHashSet.
    public static Cell<int> FirstAddToTheEmptyImmutableHashSet() =>
        Cell.Loop<int>().WithoutCaptures(l => { Kept.Add(ImmutableHashSet<SameOwn>.Empty.Add(new(l.Map(v => v)))); return S.Hold(0); });

    // S2174. The same for the first key of an empty Dictionary.
    public static Cell<int> FirstKeyOfAnEmptyDictionary() =>
        Cell.Loop<int>().WithoutCaptures(l => { Dictionary<SameOwn, int> made = new(); made.Add(new(l.Map(v => v)), 1); return S.Hold(0); });

    // S2175. The same for a HashSet whose constructor gets only a capacity.
    public static Cell<int> FirstAddToAHashSetWithACapacity() =>
        Cell.Loop<int>().WithoutCaptures(l => { HashSet<SameOwn> made = new(4); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2176. The first Add to an empty HashSet makes a hash code from its value.
    public static Cell<int> FirstAddToAnEmptyHashSetMakesAHashCode() =>
        Cell.Loop<int>().WithoutCaptures(l => { HashSet<HashedOwn> made = new(); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2177. The second Add to a SortedSet compares its value with the first one.
    public static Cell<int> SecondAddToASortedSet() =>
        Cell.Loop<int>().WithoutCaptures(l => { SortedSet<RankedOwn> made = new(); made.Add(new(Plain)); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2178. A helper puts an object into the SortedSet before the first Add of the block.
    public static Cell<int> FirstAddAfterAHelperGotTheSortedSet() =>
        Cell.Loop<int>().WithoutCaptures(l => { SortedSet<RankedOwn> made = new(); PutOneRankedOwn(made); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2179. The first Add of the block is in a loop, and the second turn compares.
    public static Cell<int> FirstAddToASortedSetInALoop() =>
        Cell.Loop<int>().WithoutCaptures(l => { SortedSet<RankedOwn> made = new(); for (int i = 0; i < 2; i++) { made.Add(new(l.Map(v => v))); } return S.Hold(0); });

    // S2180. The constructor of the SortedSet gets an object.
    public static Cell<int> FirstAddToASortedSetFromASequence() =>
        Cell.Loop<int>().WithoutCaptures(l => { SortedSet<RankedOwn> made = new(new[] { new RankedOwn(Plain) }); made.Add(new(l.Map(v => v))); return S.Hold(0); });

    // S2181. A lambda does the first Add of the text, and the block calls it after a second Add.
    public static Cell<int> FirstAddInALambdaThatRunsAfterASecondAdd() =>
        Cell.Loop<int>().WithoutCaptures(l => { SortedSet<RankedOwn> made = new(); Action add = () => made.Add(new(l.Map(v => v))); made.Add(new(Plain)); add(); return S.Hold(0); });

    // S2182. A pending cell goes from a first local to a second one in the turn after, and the third turn samples it.
    public static Cell<int> CellFromTwoTurnsBefore() =>
        Cell.Loop<int>().WithoutCaptures(l => { Cell<int>? a = null; Cell<int>? b = null; for (int i = 0; i < 3; i++) { if (b != null) { Kept.Add(b.Sample()); } b = a; a = l.Map(v => v); } return S.Hold(0); });

    // S2183. The same through three locals, and the fourth turn samples it.
    public static Cell<int> CellFromThreeTurnsBefore() =>
        Cell.Loop<int>().WithoutCaptures(l => { Cell<int>? a = null; Cell<int>? b = null; Cell<int>? c = null; for (int i = 0; i < 4; i++) { if (c != null) { Kept.Add(c.Sample()); } c = b; b = a; a = l.Map(v => v); } return S.Hold(0); });

    // S2184. An object with a pending cell goes through two locals, and the third turn samples its cell.
    public static Cell<int> ObjectFromTwoTurnsBefore() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot? a = null; SettableSlot? b = null; for (int i = 0; i < 3; i++) { if (b != null) { Kept.Add(b.Share!.Sample()); } b = a; a = new SettableSlot { Share = l.Map(v => v) }; } return S.Hold(0); });

    // S2185. A plain cell goes through two locals, and the third turn samples it.
    public static Cell<int> PlainCellFromTwoTurnsBefore() =>
        Cell.Loop<int>().WithoutCaptures(l => { Cell<int>? a = null; Cell<int>? b = null; for (int i = 0; i < 3; i++) { if (b != null) { Kept.Add(b.Sample()); } b = a; a = Plain; } return S.Hold(0); });

    // S2186. A function of a query makes an object with two names for each element. A pending cell through the second name is a change for the first one.
    public static Cell<int> TwoNamesInAFunctionOfAQuery() =>
        Cell.Loop<int>().WithoutCaptures(l => { int[] made = new[] { 1 }.Select(n => { SettableSlot x = new() { Share = Plain }; SettableSlot y = x; y.Share = l.Map(v => v); return x.Share!.Sample(); }).ToArray(); Kept.Add(made); return S.Hold(0); });

    // S2187. The same in a lambda that a list runs for each element.
    public static Cell<int> TwoNamesInALambdaThatAListRuns() =>
        Cell.Loop<int>().WithoutCaptures(l => { new List<int> { 1 }.ForEach(n => { SettableSlot x = new() { Share = Plain }; SettableSlot y = x; y.Share = l.Map(v => v); Kept.Add(x.Share!.Sample()); }); return S.Hold(0); });

    // S2188. A lambda that a list runs for each element makes an object, and a plain cell through a second name replaces its pending cell.
    public static Cell<int> PlainThroughASecondNameInALambdaThatAListRuns() =>
        Cell.Loop<int>().WithoutCaptures(l => { new List<int> { 1 }.ForEach(n => { SettableSlot x = new() { Share = l.Map(v => v) }; SettableSlot y = x; y.Share = Plain; Kept.Add(x.Share!.Sample()); }); return S.Hold(0); });

    // S2189. A lambda that a list runs for each element gives its object a plain cell in a branch that does not run.
    public static Cell<int> PlainInABranchOfALambdaThatAListRuns() =>
        Cell.Loop<int>().WithoutCaptures(l => { new List<int> { 1 }.ForEach(n => { SettableSlot x = new() { Share = l.Map(v => v) }; if (n > 5) { x.Share = Plain; } Kept.Add(x.Share!.Sample()); }); return S.Hold(0); });

    // S2190. A local function that a list runs for each element makes an object with two names.
    public static Cell<int> TwoNamesInALocalFunctionThatAListRuns() =>
        Cell.Loop<int>().WithoutCaptures(l => { void Each(int n) { SettableSlot x = new() { Share = Plain }; SettableSlot y = x; y.Share = l.Map(v => v); Kept.Add(x.Share!.Sample()); } new List<int> { 1 }.ForEach(Each); return S.Hold(0); });

    // S2191. The same, where a plain cell through the second name replaces the pending cell.
    public static Cell<int> PlainThroughASecondNameInALocalFunctionThatAListRuns() =>
        Cell.Loop<int>().WithoutCaptures(l => { void Each(int n) { SettableSlot x = new() { Share = l.Map(v => v) }; SettableSlot y = x; y.Share = Plain; Kept.Add(x.Share!.Sample()); } new List<int> { 1 }.ForEach(Each); return S.Hold(0); });

    // S2192. A lambda that a list runs for each element samples the cell that the run before gave to a local of the block.
    public static Cell<int> RunBeforeOfALambdaThatAListRunsGaveAPendingCell() =>
        Cell.Loop<int>().WithoutCaptures(l => { Cell<int>? last = null; new List<int> { 1, 2 }.ForEach(n => { if (last != null) { Kept.Add(last.Sample()); } last = l.Map(v => v); }); return S.Hold(0); });

    // S2193. A lambda that a branch calls makes its own object, and gives it a plain cell after a pending one.
    public static Cell<int> PlainAfterPendingInALambdaThatABranchCalls() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<Cell<int>, int> own = share => { SettableSlot x = new() { Share = share }; x.Share = Plain; return x.Share!.Sample(); }; if (!Never) { Kept.Add(own(l.Map(v => v))); } return S.Hold(0); });

    // S2194. A lambda that a branch calls calls a second lambda as a statement. The second lambda gives the object of the block a plain cell, and the branch does not run.
    public static Cell<int> PlainThroughALambdaOfALambdaThatABranchCalls() =>
        Cell.Loop<int>().WithoutCaptures(l => { Action<SettableSlot> plain = given => { given.Share = Plain; }; Action<SettableSlot> through = given => { plain(given); }; SettableSlot x = new() { Share = l.Map(v => v) }; if (Never) { through(x); } return S.Hold(x.Share!.Sample()); });

    // S2195. A lambda with an expression for its body calls a second lambda, which gives the object of the block a plain cell.
    public static Cell<int> PlainThroughALambdaWithAnExpressionBody() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<SettableSlot, int> plain = given => { given.Share = Plain; return 0; }; Func<SettableSlot, int> through = given => plain(given); SettableSlot x = new() { Share = l.Map(v => v) }; Kept.Add(through(x)); return S.Hold(x.Share!.Sample()); });

    // S2196. The same for a local function with an expression for its body.
    public static Cell<int> PlainThroughALocalFunctionWithAnExpressionBody() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<SettableSlot, int> plain = given => { given.Share = Plain; return 0; }; int Through(SettableSlot given) => plain(given); SettableSlot x = new() { Share = l.Map(v => v) }; Kept.Add(Through(x)); return S.Hold(x.Share!.Sample()); });

    // S2197. The call of a lambda is in a return statement, before the read.
    public static Cell<int> PlainThroughALambdaWhoseCallIsInAReturn() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<SettableSlot, int> plain = given => { given.Share = Plain; return 0; }; SettableSlot x = new() { Share = l.Map(v => v) }; return S.Hold(plain(x) + x.Share!.Sample()); });

    // S2198. The call of a lambda is the right side of an operator that does not read it, where the left side is true.
    public static Cell<int> PlainThroughALambdaAfterAnOrOperator() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<SettableSlot, bool> plain = given => { given.Share = Plain; return true; }; SettableSlot x = new() { Share = l.Map(v => v) }; bool b = !Never || plain(x); Kept.Add(b); return S.Hold(x.Share!.Sample()); });

    // S2199. The call of a lambda is the right side of a coalescing assignment whose target has a value.
    public static Cell<int> PlainThroughALambdaInACoalescingAssignment() =>
        Cell.Loop<int>().WithoutCaptures(l => { Func<SettableSlot, int> plain = given => { given.Share = Plain; return 0; }; SettableSlot x = new() { Share = l.Map(v => v) }; int? known = Kept.Count >= 0 ? 1 : null; known ??= plain(x); Kept.Add(known); return S.Hold(x.Share!.Sample()); });

