    public sealed class DvVmDetailViewModel : IDisposable
    {
        internal readonly Cell<int> revision;

        internal DvVmDetailViewModel(IDvVmText title, IDvVmAction save, Cell<int> revision)
        {
            this.Title = title;
            this.Save = save;
            this.revision = revision;
        }

